const DATA={"modules":[],"advanced":{"1.1":[["An operations VP says, “Training never changes performance.” What is your best opening?",["Explain instructional design terminology","Acknowledge the concern, clarify desired business outcomes and offer relevant evidence","Defend your previous courses","Send an unrelated brochure"],1,"Lead with the leader’s concern and performance outcome."],["A participant sends an upset email after a facilitation incident. What next?",["Reply defensively to the entire group","Acknowledge the concern and arrange a private clarification conversation","Ignore it for one week","Publicly challenge the account"],1,"Sensitive feedback benefits from acknowledgement and a private dialogue."],["The head of HR requests approval of an onboarding redesign. Which value proposition is most compelling?",["We will add 20 slides","We aim to reduce avoidable onboarding mistakes, using targeted practice and a measured pilot","The course uses a fashionable method","All staff should attend more training"],1,"State value in business-relevant terms and propose credible measurement."]],"1.2":[["A facilitator interprets a silent virtual participant as hostile. What should happen?",["Document poor attitude immediately","Check the context and invite participation without assumptions","Remove them from the meeting","Ignore future contributions"],1,"Avoid turning one observation into an unsupported judgment."],["A manager is selecting three employees for a prestigious development program. What should HR recommend?",["Use personal impressions only","Agree on transparent criteria and check possible bias","Select the longest-tenured employees automatically","Ask only one supervisor"],1,"Structured criteria support equitable decisions."],["Your pilot receives negative feedback an hour before leadership review. What demonstrates both EI and resilience?",["Hide the results","Regulate your reaction, review evidence and present corrective actions","Blame staff","Cancel all learning programs"],1,"Respond constructively while remaining accountable."]],"1.3":[["Two department heads disagree about ownership of a learning initiative. How should you facilitate?",["Choose the senior leader’s preference","Clarify shared goals, decision rights and evidence before options","Let the issue continue","Call a vote without discussion"],1,"Shared outcome and roles prevent unproductive conflict."],["A junior designer is delegated a training pilot. What should the manager do?",["Assign it without authority","Agree on the outcome, resources, authority and check-in dates","Insist on approving every minor decision","Transfer all accountability"],1,"Delegation requires support and appropriate decision authority."],["A cross-functional committee spends most of its week in update meetings. What is a useful intervention?",["Schedule more status meetings","Simplify meetings and clarify decision ownership and asynchronous updates","Remove collaboration entirely","Ignore workload"],1,"Reduce unnecessary coordination cost while preserving essential teamwork."]],"1.4":[["A multinational academy proposes one training format for everyone based on national stereotypes. What should the TD lead propose?",["Require every region to conform","Conduct learner research and adapt for accessibility, local context and common standards","Remove feedback channels","Assume all learners in a country think alike"],1,"Design around actual learner needs; balance consistency with contextual adaptation."],["An audit finds that high-potential nominations are informal and inconsistent across departments. What intervention is strongest?",["Publicly name managers who made nominations","Define transparent eligibility criteria, review access patterns and support managers","Remove all development opportunities","Add generic DEI slides"],1,"Governance and evidence help address systemic access barriers."],["A hybrid training cohort has uneven contributions across locations. What should the facilitator do first?",["Interpret quiet participation as lack of motivation","Check access and participation barriers, set inclusive ground rules and vary participation formats","Only call on the most vocal people","Disable chat and captions"],1,"Facilitation should remove participation barriers before inferring motives."]],"1.5":[["A learning platform launch has a fixed date and a requested scope increase. What is the best project response?",["Promise unchanged cost and quality","Evaluate tradeoffs and present options to the sponsor using change control","Skip all testing","Hide the change from stakeholders"],1,"The sponsor needs explicit tradeoffs among scope, time, cost, quality and resources."],["An L&D team has conflicting estimates for development and validation. What should the project manager do?",["Guess a midpoint with no discussion","Map dependencies, validate estimates with owners and update the baseline with approval","Remove review stages","Use a generic vendor estimate without checking"],1,"Effective planning uses task owners and realistic dependencies."],["A sponsor wants only positive weekly project updates despite slipping milestones. What should the PM do?",["Report only green indicators","Communicate factual variance, implications, options and decisions required","Stop issuing status updates","Blame the stakeholders"],1,"Transparent reporting enables timely corrective decisions."]],"1.6":[["An executive asks the academy to distribute individual personality-test results widely to encourage transparency. What is the strongest response?",["Share all raw results","Check consent, access rights, assessment conditions and privacy obligations before sharing","Post only the lowest scores","Delete all records without policy review"],1,"Assessment information requires privacy safeguards and authorized use."],["A course developer has copied a licensed model illustration from a paid book into a public LMS. How should the lead respond?",["Assume attribution eliminates infringement","Check permissions and replace with a licensed or original visual if needed","Remove the copyright notice only","Ignore the issue because the image teaches a skill"],1,"Attribution does not by itself authorize reuse."],["A training assessment will determine which employees receive promotions. Which safeguard matters most?",["An attractive user interface","Job-relevant validation, consistent administration and legal review","A difficult pass mark chosen at random","Anonymizing the instructor’s name"],1,"High-stakes employment uses demand fairness and defensible measures."]],"1.7":[["Employees complete many courses but transfer little to work. What would improve the learning system most?",["Add more content without practice","Connect learning goals to job assignments, feedback and transfer evidence","Count page views as mastery","Remove manager involvement"],1,"Learning success depends on application and reinforcement."],["An employee wants a future role requiring strategic consulting. How should TD support the development plan?",["Offer only a short definition of consulting","Map needed capabilities, assign real consulting practice, coaching and checkpoints","Guarantee a promotion","Ignore the employee’s current skills"],1,"Role-based capability development combines learning and experience."],["A business unit has low voluntary learning participation. What should the academy investigate?",["Assume employees lack curiosity","Examine relevance, manager support, access, workload and motivation barriers","Mandate daily reading without context","Remove self-paced options"],1,"Environmental conditions and relevance strongly affect engagement."]],"2.1":[["A service organization found that new employees pass a knowledge quiz but repeat task errors on shift. As TD lead, what should you change first?",["Raise the pass mark without support","Analyze task barriers and add guided practice, feedback and spaced retrieval on the job","Send all learners a long handbook","Remove the quiz"],1,"Transfer requires real task practice, timely feedback and attention to barriers."],["An online lesson has unrelated animation, dense paragraphs and little learner practice. What is the best redesign?",["Shorten the text, align visuals to the task and include retrieval practice","Add more decorative animation","Increase reading speed","Make learning passive"],0,"Coherent segmentation and active retrieval improve processing."],["A sponsor claims a neuroscience-based product guarantees learning. What should TD request?",["Testimonials only","Methodology, supporting evidence and independent evaluation","A faster purchasing contract","More promotional slides"],1,"Evaluate evidence and research methods before adopting strong claims."]],"2.2":[["A VP asks for compliance training, but data show employees lack access to updated policy documents. What should TD recommend?",["Only a mandatory course","Address the information-access issue first; train only on genuine skill needs","A longer lecture","A higher quiz pass mark"],1,"Performance analysis can identify a nonlearning root cause."],["An objective expects a complex coaching conversation; the proposed assessment tests vocabulary. What should happen?",["Keep the vocabulary test alone","Add a simulation assessed with criteria for the actual conversation","Remove practice","Use only satisfaction surveys"],1,"Assessment must measure the performance stated in the objective."],["SMEs disagree about a procedure after a prototype user test. How should a designer proceed?",["Choose whichever SME is most senior","Verify the process against job evidence and approved standards, revise and retest","Publish both contradictory procedures","Skip the review"],1,"Content decisions require verified accuracy and iterative feedback."]],"2.3":[["A business sponsor needs improved results related to training delivery & facilitation. What should the TD professional do first?",["Select the most fashionable delivery technology","Define the performance problem, stakeholder expectations and observable success criteria","Launch a course before investigating causes","Use learner satisfaction alone as the success criterion"],1,"Performance analysis and stakeholder alignment should precede learning or technology decisions."],["A cross-functional rollout of training delivery & facilitation has uneven adoption across locations. Which action is strongest?",["Require every team to use an identical approach regardless of context","Stop gathering feedback after launch","Collect representative user evidence, address barriers and adjust the solution against defined objectives","Report attendance as proof of impact"],2,"Use representative evidence and iterative improvement rather than assumptions or attendance alone."],["A senior leader wants an immediate success report before the project can show on-the-job change. What should TD do?",["Report confirmed outputs separately from longer-term outcomes and establish follow-up measurement","Claim workplace performance has improved based on a quiz score","Discard the project evaluation plan","Use only anecdotal testimonials"],0,"Learning participation, learning gain, application and organizational impact are distinct types of evidence."]],"2.4":[["A business sponsor needs improved results related to technology application. What should the TD professional do first?",["Select the most fashionable delivery technology","Define the performance problem, stakeholder expectations and observable success criteria","Launch a course before investigating causes","Use learner satisfaction alone as the success criterion"],1,"Performance analysis and stakeholder alignment should precede learning or technology decisions."],["A cross-functional rollout of technology application has uneven adoption across locations. Which action is strongest?",["Require every team to use an identical approach regardless of context","Stop gathering feedback after launch","Collect representative user evidence, address barriers and adjust the solution against defined objectives","Report attendance as proof of impact"],2,"Use representative evidence and iterative improvement rather than assumptions or attendance alone."],["A regional training manager launches a mobile LMS in sites with intermittent connectivity. Adoption reports show no course completions from two remote locations. What should the technology team investigate first?",["Remove the remote sites from the reporting denominator","Validate offline access, synchronization logs and device compatibility with affected users before interpreting their learning outcomes","Require daily screenshot submissions instead of solving access issues","Replace the LMS immediately without investigating failure patterns"],1,"Technology access and synchronization evidence must be checked before interpreting missing completions as learner disengagement."]],"2.5":[["A business sponsor needs improved results related to knowledge management. What should the TD professional do first?",["Select the most fashionable delivery technology","Define the performance problem, stakeholder expectations and observable success criteria","Launch a course before investigating causes","Use learner satisfaction alone as the success criterion"],1,"Performance analysis and stakeholder alignment should precede learning or technology decisions."],["A cross-functional rollout of knowledge management has uneven adoption across locations. Which action is strongest?",["Require every team to use an identical approach regardless of context","Stop gathering feedback after launch","Collect representative user evidence, address barriers and adjust the solution against defined objectives","Report attendance as proof of impact"],2,"Use representative evidence and iterative improvement rather than assumptions or attendance alone."],["Two retiring engineers hold critical troubleshooting knowledge that is absent from the knowledge base. Production incidents are increasing. What should the knowledge manager prioritize?",["Ask the engineers to upload everything with no structure","Capture critical decision paths through guided interviews and observed work, validate them with peers, and make them searchable at the point of need","Wait for new hires to independently discover the same solutions","Replace the knowledge base with attendance records from past training"],1,"Knowledge continuity requires capturing validated tacit expertise and embedding it in usable work guidance."]],"2.6":[["An executive asks for a rapid initiative connected to career & leadership development. What is the strongest first step?",["Buy a technology before defining a need","Define stakeholder objectives, performance needs, ethical constraints and success measures","Launch an identical course for every role","Treat attendance as verified performance"],1,"Align with business and learner needs, appropriate governance and measurable outcomes first."],["A rollout of career & leadership development is showing uneven results and employees raise fairness concerns. What should TD do?",["Dismiss concerns because the sponsor approved the project","Apply the same intervention without examination","Review representative evidence and access barriers, consult stakeholders and adapt the initiative","Only publish the average satisfaction rating"],2,"Fair access and reliable data are essential to defensible talent management recommendations."],["A project report demonstrates learning gains but contains no follow-up workplace evidence. What should the TD professional conclude?",["Learning gains were observed; measure application and business outcomes separately","The entire business performance problem is solved","Promotion readiness is proven","No more evaluation could add value"],0,"Distinguish learning measures from observed on-the-job performance and organizational outcomes."]],"2.7":[["An executive asks for a rapid initiative connected to coaching. What is the strongest first step?",["Buy a technology before defining a need","Define stakeholder objectives, performance needs, ethical constraints and success measures","Launch an identical course for every role","Treat attendance as verified performance"],1,"Align with business and learner needs, appropriate governance and measurable outcomes first."],["A rollout of coaching is showing uneven results and employees raise fairness concerns. What should TD do?",["Dismiss concerns because the sponsor approved the project","Apply the same intervention without examination","Review representative evidence and access barriers, consult stakeholders and adapt the initiative","Only publish the average satisfaction rating"],2,"Fair access and reliable data are essential to defensible talent management recommendations."],["A coaching program reports high satisfaction, but managers rarely conduct follow-up conversations and coachees show no documented behavior changes. What should the coaching lead do?",["Declare success because participants liked the coach","Agree on observable coaching goals, follow-up evidence and manager support while maintaining appropriate confidentiality","Publish confidential coaching conversations to increase accountability","Replace all coaches based solely on satisfaction ratings"],1,"Coaching effectiveness needs agreed behavioral evidence and ethically appropriate follow-up, not only reaction data."]],"2.8":[["An executive asks for a rapid initiative connected to evaluating impact. What is the strongest first step?",["Buy a technology before defining a need","Define stakeholder objectives, performance needs, ethical constraints and success measures","Launch an identical course for every role","Treat attendance as verified performance"],1,"Align with business and learner needs, appropriate governance and measurable outcomes first."],["A rollout of evaluating impact is showing uneven results and employees raise fairness concerns. What should TD do?",["Dismiss concerns because the sponsor approved the project","Apply the same intervention without examination","Review representative evidence and access barriers, consult stakeholders and adapt the initiative","Only publish the average satisfaction rating"],2,"Fair access and reliable data are essential to defensible talent management recommendations."],["A training pilot reduces errors in the pilot branch, while comparison branches also improve after a company-wide process change. How should the evaluator report program impact?",["Attribute all improvement to the training intervention","Separate concurrent operational changes, compare trends and disclose attribution limits before estimating contribution","Ignore comparison branches and publish the strongest improvement percentage","Remove data that conflict with the desired narrative"],1,"Evaluating impact requires identifying confounding influences and reporting evidence with appropriate causal caution."]],"3.1":[["A retail chain asks TD to justify a large onboarding investment after customer complaints rise. Finance wants credible return on investment but the store processes have also changed. What is the best evidence-led proposal?",["Report attendance and predicted ROI without assumptions","Link observed service behaviors to service KPIs, quantify costs and benefits, document process changes as confounders","Focus entirely on learner satisfaction","Promise a fixed revenue increase"],1,"A credible proposal links behavior to results while accounting for other causes and disclosing estimates."],["A nonprofit wants to expand its services, but board members disagree about success measures. What should TD do before preparing talent pathways?",["Use profit margin as the only success measure","Clarify mission-driven outcomes and capability requirements with key stakeholders","Copy a for-profit leadership curriculum","Increase course completions as the target"],1,"Mission and stakeholder-defined results determine the capability strategy."]],"3.2":[["A business sponsor insists on a training program, but field observations reveal broken equipment and unrealistic scheduling. What should the consultant recommend?",["Build training as requested without mentioning the findings","Explain the performance causes and jointly consider operational and targeted learning interventions","Tell employees to work harder","Conceal observations to protect the relationship"],1,"The consultant must ground recommendations in a system diagnosis and consider nontraining barriers."],["An external consultant proposes a solution that clashes with local culture and bypasses an influential operational group. What is the best course?",["Adopt the package unchanged","Reassess stakeholder needs and co-design a workable solution within the agreed scope","Ignore informal influence","Withdraw all consulting support"],1,"Partnership and systems thinking require adaptation to the organizational context."]],"3.3":[["A company introduces new learning software but employees still avoid sharing knowledge because supervisors reward solo performance. Which OD intervention is most appropriate?",["Assign a software tutorial only","Realign leader behavior, incentives and workflow expectations, while monitoring collaboration outcomes","Increase compulsory login targets","Leave existing performance reviews unchanged"],1,"Organization development addresses interacting systems, not a single technology artifact."],["An engagement survey shows deteriorating trust, but managers want to launch a new wellness webinar immediately. What is the best next move?",["Launch the webinar and declare the issue resolved","Share findings with appropriate protections, investigate underlying conditions and co-create measurable actions","Disclose named confidential responses","Stop surveying to avoid negative findings"],1,"Engagement and well-being require ethical diagnosis, shared action and follow-through."],["A learning culture initiative shows good attendance but little change to daily collaboration. How should OD respond?",["Increase attendance targets only","Evaluate work incentives, manager coaching, knowledge flow and real behavior, then adjust the system","Replace all employees","End evaluation because learners are satisfied"],1,"Sustainable culture change depends on leadership, work systems and observable behaviors."]],"3.4":[["Advanced case · 3.4.1: Workforce planning identifies a leadership skill shortage. How should talent functions work together?",["Proceed without analyzing implications or affected stakeholders.","Connect shared competency data to recruitment, development, succession, performance and rewards.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.4.9: Managers say learning is an L&D responsibility and never allow time to practice. What should TD do?",["Proceed without analyzing implications or affected stakeholders.","Build an executive-supported learning culture with manager accountability and work-based development.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.4.16: Managers give feedback only at annual ratings discussions. What redesign is strongest?",["Proceed without analyzing implications or affected stakeholders.","Use ongoing goals, coaching, role-relevant evidence, development actions and regular check-ins.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."]],"3.5":[["Advanced case · 3.5.1: Workers fail a service target although they passed a knowledge test; the system is slow. What first response fits HPI?",["Proceed without analyzing implications or affected stakeholders.","Investigate work processes, technology and performance influences before prescribing training.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.5.4: One team consistently outperforms peers. How can TD improve performance analysis?",["Proceed without analyzing implications or affected stakeholders.","Observe key performers and compare the steps, information and enablers they use with standard practice.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.5.7: A proposed training fix shifts workload to another team and increases errors. What was missed?",["Proceed without analyzing implications or affected stakeholders.","Systems interactions, downstream effects and clear boundaries of the original performance diagnosis.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."]],"3.6":[["Advanced case · 3.6.1: Staff understand why change is needed but cannot perform the new workflow. What ADKAR element is missing?",["Proceed without analyzing implications or affected stakeholders.","Ability: provide practice, tools, coaching and time to perform the new behavior.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.6.3: Employees oppose a new tool because it removes autonomy. How should change leaders respond?",["Proceed without analyzing implications or affected stakeholders.","Understand the legitimate restraining forces, offer meaningful choices and mitigate risks.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.6.4: A major change initiative starts without a visible sponsor or success criteria. What should be done?",["Proceed without analyzing implications or affected stakeholders.","Secure leadership sponsorship, define current and future states, assign roles and establish measures.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."]],"3.7":[["Advanced case · 3.7.1: A CHRO wants to understand why turnover increased last quarter. Which analytics type fits?",["Proceed without analyzing implications or affected stakeholders.","Diagnostic analytics to investigate causes using evidence and alternative explanations.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.7.4: Training and productivity increase together. What can an analyst report responsibly?",["Proceed without analyzing implications or affected stakeholders.","An association that needs further investigation; correlation alone does not establish causation.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.7.7: A predictive attrition score is shared with managers who then deny development to high-risk employees. What is the core problem?",["Proceed without analyzing implications or affected stakeholders.","Unethical people-analytics use; protect privacy, fairness and appropriate decision governance.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."]],"3.8":[["Advanced case · 3.8.1: A strategy shift introduces automation and cross-border hybrid teams. What should TD examine?",["Proceed without analyzing implications or affected stakeholders.","Internal and external drivers and their implications for future workforce skills and learning systems.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.8.4: A vendor promises immersive learning will solve every performance gap. What should TD do?",["Proceed without analyzing implications or affected stakeholders.","Assess fit, readiness, risks, security, cost and actual performance needs before procurement.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."],["Advanced case · 3.8.6: A leader succeeds in familiar situations but struggles in a new role. Which approach builds agility?",["Proceed without analyzing implications or affected stakeholders.","Use reflection, feedback, stretching experiences and transfer of lessons to unfamiliar situations.","Measure course participation only and ignore operating results.","Change the plan without agreeing on measures or ownership."],1,"Strong judgment is anchored in the specific capability, stakeholders and measurable organizational outcomes."]]},"domain3":[["3.1","Business Insight"],["3.2","Consulting & Business Partnering"],["3.3","Organization Development & Culture"],["3.4","Talent Strategy & Management"],["3.5","Performance Improvement"],["3.6","Change Management"],["3.7","Data & Analytics"],["3.8","Future Readiness"]],"domain2Questions":{"2.1":[["A team completed a webinar but cannot apply the process two weeks later. What should the TD professional prioritize?",["Extend the webinar duration","Add spaced practice with real job tasks and feedback","Increase the number of slides","Require attendance certificates"],1,"Practice, retrieval and feedback increase the likelihood of transfer."],["Learners have different prior experience with a new system. What is the best initial design decision?",["Deliver identical introductory content regardless of skill","Group everyone by job title only","Use a diagnostic and offer differentiated practice","Remove the practice exercises"],2,"A diagnostic helps match practice and scaffolding to prior knowledge."],["A facilitator wants learners to retain a complex procedure. Which approach best limits cognitive overload?",["Present the full process in a single dense diagram","Break the process into meaningful steps with worked examples","Include multiple unrelated animations","Introduce every exception before the basic steps"],1,"Chunking and worked examples support working memory and schema development."]],"2.2":[["A business sponsor requests leadership training because engagement scores fell. What should the designer do first?",["Select a course vendor","Confirm the performance gap, its causes and intended outcomes","Create a new slide deck","Schedule a launch date"],1,"Needs and performance analysis precede solution selection."],["Which objective provides the strongest basis for assessment?",["Understand effective coaching","Appreciate the importance of feedback","Given a case, choose a feedback response and justify it against two criteria","Learn about coaching models"],2,"Observable action and criteria permit valid assessment."],["A module tests definitions, but the job requires handling a difficult employee conversation. What is the best adjustment?",["Increase the number of definition questions","Use a realistic branching conversation with performance-based feedback","Remove formative assessment","Replace all activities with reading"],1,"Assessments should align with the intended job performance."]],"2.3":[["During a virtual workshop, only two participants speak while others remain silent. What is the best next step?",["Call on silent participants without warning","Use structured small-group reflection and invite multiple response channels","Continue because silence means agreement","Cancel the discussion"],1,"Structured participation can improve inclusion and diagnostic insight."],["A participant challenges a facilitator with a valid example. What should the facilitator do?",["Defend the original slide immediately","Acknowledge the example, explore the evidence and connect it to the objective","Ignore it to protect the schedule","Ask the participant to leave"],1,"Good facilitation uses inquiry, neutrality and evidence."],["An instructor sees repeated confusion over a key step. What is the best response?",["Proceed because the agenda is fixed","Check understanding, reteach using an alternative example, then reassess","Repeat the same sentence louder","Assign all participants a failing grade"],1,"Responsive facilitation changes instruction based on learner evidence."]],"2.4":[["A team proposes a new learning platform with impressive features. What should TD evaluate first?",["Which platform has the most features","Fit with learner needs, intended outcomes, accessibility and integration","Which platform has the newest interface","Which vendor offers the most templates"],1,"Technology choice follows the learning and performance requirements."],["Employees access learning mainly through mobile devices and unreliable connections. What design choice is strongest?",["Large auto-playing video files only","Mobile-responsive, low-bandwidth resources with downloadable alternatives","Desktop-only simulations","Mandatory video calls for all practice"],1,"Design should fit the actual access constraints."],["A video-based course has learners who require captions. What is the best action?",["Provide captions/transcripts and test accessibility before rollout","Ask learners to find a different course","Only provide louder audio","Use smaller text on the slides"],0,"Accessible alternatives need to be built into delivery."]],"2.5":[["Critical expertise is leaving with a retiring specialist. What should TD do first?",["Record every meeting without a plan","Identify critical tacit knowledge and design structured capture and transfer","Publish a generic document repository","Assume formal SOPs contain everything"],1,"Knowledge risk analysis focuses capture on valuable, at-risk expertise."],["Employees cannot find the latest procedure and use outdated versions. What is the priority?",["Upload additional untagged documents","Define ownership, versioning, search metadata and review cycles","Remove all procedures","Ask each team to create separate private copies"],1,"Governance and findability are fundamental to useful knowledge management."],["A community of practice has low engagement. What is the most appropriate intervention?",["Require long weekly status reports","Define a practical shared problem and encourage useful peer exchange","Post only leadership announcements","Prevent questions that challenge current practice"],1,"Communities need relevant purpose, contribution and shared value."]],"2.6":[["A high-potential program selects only employees nominated informally by managers. What is the main design concern?",["The program needs more promotional materials","Criteria may be inconsistent and restrict equitable access","Participants should not have career goals","Programs should ignore succession needs"],1,"Transparent, job-related criteria reduce bias and improve fairness."],["An employee wants to move into a leadership role in two years. What should TD recommend?",["Only enroll in generic lectures","Assess required capabilities and create a development plan with stretch experiences and feedback","Guarantee promotion after training","Focus only on current tasks"],1,"Development should address future-role gaps through multiple learning experiences."],["A succession plan lists names but no evidence of readiness. What should improve?",["Replace readiness criteria with tenure","Define role requirements, assess readiness and plan targeted development","Hide development expectations from managers","Increase the number of names"],1,"Succession effectiveness depends on capability evidence and readiness development."]],"2.7":[["A manager asks a coach to tell an employee exactly what to do about a career decision. What is the best coaching response?",["Choose the option for the employee","Explore goals, options and consequences through questions","Avoid discussing career goals","Make a promise of promotion"],1,"Coaching supports ownership and thoughtful decisions."],["An employee repeatedly misses a goal. How should a coach begin?",["Assume low motivation","Clarify the goal and explore barriers with the employee","Threaten consequences before listening","Ignore the performance data"],1,"Good coaching starts with shared facts and an inquiry into barriers."],["A coach learns confidential personal details unrelated to work. What principle takes priority?",["Share them with the entire team","Maintain appropriate confidentiality and explain agreed boundaries","Post notes to a shared channel","Use the information in a performance rating"],1,"Ethical coaching respects confidentiality and clear boundaries."]],"2.8":[["Participants rate a course highly, but work errors have not declined. What is the best conclusion?",["The course achieved business impact","Satisfaction alone does not demonstrate behavior change; investigate transfer and results","The survey should be deleted","A longer satisfaction survey proves ROI"],1,"Impact requires evidence beyond learner reaction."],["A sponsor wants evidence that training improved onboarding speed. What is the strongest evaluation plan?",["Report total course enrollments","Define a baseline and compare relevant time-to-proficiency metrics, accounting for other factors","Count the number of slides","Use instructor impressions only"],1,"Business-aligned evaluation uses valid performance measures and context."],["A team finds that learners know a procedure but do not use it. What is the best next investigation?",["Repeat knowledge tests only","Examine workplace incentives, tools, manager support and opportunities to apply","Remove the performance outcome","Assume learners are unwilling"],1,"Transfer depends on the work environment as well as learning."]]},"domain1ScenarioQuestions":{"1.1":[{"id":"1.1-case-1","title":"Workplace scenario","q":"An operations VP says, “Training never changes performance.” What is your best opening?","opts":["Explain instructional design terminology","Acknowledge the concern, clarify desired business outcomes and offer relevant evidence","Defend your previous courses","Send an unrelated brochure"],"answer":1,"why":"Lead with the leader’s concern and performance outcome.","target":"1.1.1"},{"id":"1.1-case-2","title":"Workplace scenario","q":"A participant sends an upset email after a facilitation incident. What next?","opts":["Reply defensively to the entire group","Acknowledge the concern and arrange a private clarification conversation","Ignore it for one week","Publicly challenge the account"],"answer":1,"why":"Sensitive feedback benefits from acknowledgement and a private dialogue.","target":"1.1.2"},{"id":"1.1-case-3","title":"Workplace scenario","q":"The head of HR requests approval of an onboarding redesign. Which value proposition is most compelling?","opts":["We will add 20 slides","We aim to reduce avoidable onboarding mistakes, using targeted practice and a measured pilot","The course uses a fashionable method","All staff should attend more training"],"answer":1,"why":"State value in business-relevant terms and propose credible measurement.","target":"1.1.3"}],"1.2":[{"id":"1.2-case-1","title":"Workplace scenario","q":"A facilitator interprets a silent virtual participant as hostile. What should happen?","opts":["Document poor attitude immediately","Check the context and invite participation without assumptions","Remove them from the meeting","Ignore future contributions"],"answer":1,"why":"Avoid turning one observation into an unsupported judgment.","target":"1.2.1"},{"id":"1.2-case-2","title":"Workplace scenario","q":"A manager is selecting three employees for a prestigious development program. What should HR recommend?","opts":["Use personal impressions only","Agree on transparent criteria and check possible bias","Select the longest-tenured employees automatically","Ask only one supervisor"],"answer":1,"why":"Structured criteria support equitable decisions.","target":"1.2.2"},{"id":"1.2-case-3","title":"Workplace scenario","q":"Your pilot receives negative feedback an hour before leadership review. What demonstrates both EI and resilience?","opts":["Hide the results","Regulate your reaction, review evidence and present corrective actions","Blame staff","Cancel all learning programs"],"answer":1,"why":"Respond constructively while remaining accountable.","target":"1.2.3"}],"1.3":[{"id":"1.3-case-1","title":"Workplace scenario","q":"Two department heads disagree about ownership of a learning initiative. How should you facilitate?","opts":["Choose the senior leader’s preference","Clarify shared goals, decision rights and evidence before options","Let the issue continue","Call a vote without discussion"],"answer":1,"why":"Shared outcome and roles prevent unproductive conflict.","target":"1.3.1"},{"id":"1.3-case-2","title":"Workplace scenario","q":"A junior designer is delegated a training pilot. What should the manager do?","opts":["Assign it without authority","Agree on the outcome, resources, authority and check-in dates","Insist on approving every minor decision","Transfer all accountability"],"answer":1,"why":"Delegation requires support and appropriate decision authority.","target":"1.3.2"},{"id":"1.3-case-3","title":"Workplace scenario","q":"A cross-functional committee spends most of its week in update meetings. What is a useful intervention?","opts":["Schedule more status meetings","Simplify meetings and clarify decision ownership and asynchronous updates","Remove collaboration entirely","Ignore workload"],"answer":1,"why":"Reduce unnecessary coordination cost while preserving essential teamwork.","target":"1.3.3"}],"1.4":[{"id":"1.4-case-1","title":"Workplace scenario","q":"A multinational academy proposes one training format for everyone based on national stereotypes. What should the TD lead propose?","opts":["Require every region to conform","Conduct learner research and adapt for accessibility, local context and common standards","Remove feedback channels","Assume all learners in a country think alike"],"answer":1,"why":"Design around actual learner needs; balance consistency with contextual adaptation.","target":"1.4.1"},{"id":"1.4-case-2","title":"Workplace scenario","q":"An audit finds that high-potential nominations are informal and inconsistent across departments. What intervention is strongest?","opts":["Publicly name managers who made nominations","Define transparent eligibility criteria, review access patterns and support managers","Remove all development opportunities","Add generic DEI slides"],"answer":1,"why":"Governance and evidence help address systemic access barriers.","target":"1.4.2"},{"id":"1.4-case-3","title":"Workplace scenario","q":"A hybrid training cohort has uneven contributions across locations. What should the facilitator do first?","opts":["Interpret quiet participation as lack of motivation","Check access and participation barriers, set inclusive ground rules and vary participation formats","Only call on the most vocal people","Disable chat and captions"],"answer":1,"why":"Facilitation should remove participation barriers before inferring motives.","target":"1.4.3"}],"1.5":[{"id":"1.5-case-1","title":"Workplace scenario","q":"A learning platform launch has a fixed date and a requested scope increase. What is the best project response?","opts":["Promise unchanged cost and quality","Evaluate tradeoffs and present options to the sponsor using change control","Skip all testing","Hide the change from stakeholders"],"answer":1,"why":"The sponsor needs explicit tradeoffs among scope, time, cost, quality and resources.","target":"1.5.2"},{"id":"1.5-case-2","title":"Workplace scenario","q":"An L&D team has conflicting estimates for development and validation. What should the project manager do?","opts":["Guess a midpoint with no discussion","Map dependencies, validate estimates with owners and update the baseline with approval","Remove review stages","Use a generic vendor estimate without checking"],"answer":1,"why":"Effective planning uses task owners and realistic dependencies.","target":"1.5.3"},{"id":"1.5-case-3","title":"Workplace scenario","q":"A sponsor wants only positive weekly project updates despite slipping milestones. What should the PM do?","opts":["Report only green indicators","Communicate factual variance, implications, options and decisions required","Stop issuing status updates","Blame the stakeholders"],"answer":1,"why":"Transparent reporting enables timely corrective decisions.","target":"1.5.4"}],"1.6":[{"id":"1.6-case-1","title":"Workplace scenario","q":"An executive asks the academy to distribute individual personality-test results widely to encourage transparency. What is the strongest response?","opts":["Share all raw results","Check consent, access rights, assessment conditions and privacy obligations before sharing","Post only the lowest scores","Delete all records without policy review"],"answer":1,"why":"Assessment information requires privacy safeguards and authorized use.","target":"1.6.1"},{"id":"1.6-case-2","title":"Workplace scenario","q":"A course developer has copied a licensed model illustration from a paid book into a public LMS. How should the lead respond?","opts":["Assume attribution eliminates infringement","Check permissions and replace with a licensed or original visual if needed","Remove the copyright notice only","Ignore the issue because the image teaches a skill"],"answer":1,"why":"Attribution does not by itself authorize reuse.","target":"1.6.2"},{"id":"1.6-case-3","title":"Workplace scenario","q":"A training assessment will determine which employees receive promotions. Which safeguard matters most?","opts":["An attractive user interface","Job-relevant validation, consistent administration and legal review","A difficult pass mark chosen at random","Anonymizing the instructor’s name"],"answer":1,"why":"High-stakes employment uses demand fairness and defensible measures.","target":"1.6.3"}],"1.7":[{"id":"1.7-case-1","title":"Workplace scenario","q":"Employees complete many courses but transfer little to work. What would improve the learning system most?","opts":["Add more content without practice","Connect learning goals to job assignments, feedback and transfer evidence","Count page views as mastery","Remove manager involvement"],"answer":1,"why":"Learning success depends on application and reinforcement.","target":"1.7.1"},{"id":"1.7-case-2","title":"Workplace scenario","q":"An employee wants a future role requiring strategic consulting. How should TD support the development plan?","opts":["Offer only a short definition of consulting","Map needed capabilities, assign real consulting practice, coaching and checkpoints","Guarantee a promotion","Ignore the employee’s current skills"],"answer":1,"why":"Role-based capability development combines learning and experience.","target":"1.7.2"},{"id":"1.7-case-3","title":"Workplace scenario","q":"A business unit has low voluntary learning participation. What should the academy investigate?","opts":["Assume employees lack curiosity","Examine relevance, manager support, access, workload and motivation barriers","Mandate daily reading without context","Remove self-paced options"],"answer":1,"why":"Environmental conditions and relevance strongly affect engagement.","target":"1.7.3"}],"2.1":[{"id":"2.1-extra-0","target":"2.1.1","title":"Workplace judgment","q":"A team completed a webinar but cannot apply the process two weeks later. What should the TD professional prioritize?","opts":["Extend the webinar duration","Add spaced practice with real job tasks and feedback","Increase the number of slides","Require attendance certificates"],"answer":1,"why":"Practice, retrieval and feedback increase the likelihood of transfer."},{"id":"2.1-extra-1","target":"2.1.2","title":"Workplace judgment","q":"Learners have different prior experience with a new system. What is the best initial design decision?","opts":["Deliver identical introductory content regardless of skill","Group everyone by job title only","Use a diagnostic and offer differentiated practice","Remove the practice exercises"],"answer":2,"why":"A diagnostic helps match practice and scaffolding to prior knowledge."},{"id":"2.1-extra-2","target":"2.1.3","title":"Workplace judgment","q":"A facilitator wants learners to retain a complex procedure. Which approach best limits cognitive overload?","opts":["Present the full process in a single dense diagram","Break the process into meaningful steps with worked examples","Include multiple unrelated animations","Introduce every exception before the basic steps"],"answer":1,"why":"Chunking and worked examples support working memory and schema development."}],"2.2":[{"id":"2.2-extra-0","target":"2.2.1","title":"Workplace judgment","q":"A business sponsor requests leadership training because engagement scores fell. What should the designer do first?","opts":["Select a course vendor","Confirm the performance gap, its causes and intended outcomes","Create a new slide deck","Schedule a launch date"],"answer":1,"why":"Needs and performance analysis precede solution selection."},{"id":"2.2-extra-1","target":"2.2.1","title":"Workplace judgment","q":"Which objective provides the strongest basis for assessment?","opts":["Understand effective coaching","Appreciate the importance of feedback","Given a case, choose a feedback response and justify it against two criteria","Learn about coaching models"],"answer":2,"why":"Observable action and criteria permit valid assessment."},{"id":"2.2-extra-2","target":"2.2.1","title":"Workplace judgment","q":"A module tests definitions, but the job requires handling a difficult employee conversation. What is the best adjustment?","opts":["Increase the number of definition questions","Use a realistic branching conversation with performance-based feedback","Remove formative assessment","Replace all activities with reading"],"answer":1,"why":"Assessments should align with the intended job performance."}],"2.3":[],"2.4":[],"2.5":[],"2.6":[],"2.7":[],"2.8":[]}};
